function evidencePanel(q){let e=LEGAL_EVIDENCE[q.id];if(!e)return `<div class="note"><b>Explicação pedagógica, ainda não auditada:</b> não usar como posição oficial certificada. Fundamento normativo e jurisprudencial específico pendente.</div>`;return `<div class="note"><b>${e.kind==='jurisprudencia'?'Fundamento jurisprudencial':'Fundamento normativo'} confirmado pontualmente:</b> ${esc(e.ref)} · consulta ${esc(e.checked)}<p>${esc(e.basis)}</p><a href="${esc(e.url)}" target="_blank" rel="noopener noreferrer">${e.kind==='jurisprudencia'?'Conferir tese oficial':'Conferir texto da norma'}</a><p class="small muted">${esc(e.limit)}</p></div>`}
// BACKLOG-ADM-001: mesmo banco, avaliador, histórico e revisão das questões autorais.
const backlogAuthored=window.AGU_AUTHORED_BACKLOG||[];
for(const q of backlogAuthored){if(!Q.some(x=>x.id===q.id)){Q.push(q);LEGAL_EVIDENCE[q.id]=q.evidence}}
window.AGUAuthoredQuestions={count:()=>Q.length,forCode:code=>Q.filter(q=>q.curricularIds?.includes(code)).map(q=>({id:q.id,topic:q.topic,title:q.title})),open:(id,keyboard=false)=>{const q=Q.find(q=>q.id===id&&q.curricularIds?.length);if(!q)return false;startQuiz(q.topic,q.id);if(keyboard)document.querySelector('#qtopic')?.focus();return true}};
